/*
 * A062333  Primes starting and ending with 3.
 * https://oeis.org/A062333
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = the nth prime whose first and last decimal digits are 3
 * Range:     u8 n <= 1, u16 n <= 279, u32 n <= 154, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   digit_len, is_prime_big, pow10, seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The sequence is generated by searching successive numbers ending in 3,
   checking that the first digit is 3 and that the number is prime. */

#include <stddef.h>          /* size_t */
#include <stdbool.h>         /* bool */

#include "../utils/pow10.h"           /* seq_t pow10(idx_t exp) */
#include "../utils/digit_len.h"       /* int digit_len(seq_t x) */
#include "../utils/is_prime_big.h"    /* bool is_prime_big(seq_t n) */
#include "../utils/seq_realloc.h"     /* seq_t *seq_realloc(seq_t *old, size_t old_cap, size_t new_cap) */

/* Return the nth prime that starts and ends with the digit 3.
   a(1) = 3.  The function works for any order of calls.                */
seq_t a(idx_t n)
{
    /* Static cache of computed terms */
    static seq_t *cache      = NULL;
    static size_t cache_len  = 0;   /* number of terms stored          */
    static size_t cache_cap  = 0;   /* allocated capacity of cache     */

    /* Static iterator: current candidate ending in 3 */
    static seq_t cand = 3;          /* first candidate               */

    /* Ensure enough capacity for requested index */
    if ((size_t)n > cache_cap) {
        size_t new_cap = cache_cap ? cache_cap * 2 : 16;
        while (new_cap < (size_t)n) new_cap <<= 1;
        cache = seq_realloc(cache, cache_cap, new_cap);
        cache_cap = new_cap;
    }

    /* Keep searching until we have n terms in the cache */
    while (cache_len < (size_t)n) {
        /* Length in decimal digits of the current candidate */
        int len = digit_len(cand);                 /* len ≥ 1 for cand > 0 */

        /* 10^(len-1) as seq_t */
        seq_t ten_pow = pow10((idx_t)(len - 1));

        /* Leading digit: cand / 10^(len-1) */
        seq_t leading = cand / ten_pow;

        /* If leading digit is 3, check primality */
        if (leading == 3) {
            if (is_prime_big(cand)) {
                cache[cache_len++] = cand;         /* store prime */
            }
        }

        /* Advance to the next number ending in 3 */
        cand += (seq_t)10;
    }

    return cache[(size_t)n - 1];
}
